<script setup lang="ts">
import {onMounted,ref} from 'vue';import {clone,getStudio,saveStudio,type StudioPayload} from './content-studio-api';
const payload=ref<StudioPayload|null>(null),message=ref(''),creating=ref(false),name=ref('');async function load(){payload.value=await getStudio()}onMounted(load);
function slug(value:string){return value.trim().toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]+/g,'-').replace(/^-|-$/g,'')||`route-${Date.now()}`}
async function create(){if(!payload.value||!name.value.trim())return;const doc=clone(payload.value.document),id=slug(name.value);if(doc.routes.some(r=>r.id===id)){message.value='该路线编号已存在，请换一个名称。';return}doc.routes.push({id,slug:id,name:{zh:name.value.trim(),en:''},summary:{zh:'',en:''},mapTitle:{zh:'',en:''},order:(doc.routes.length+1)*10,published:false,featured:false,archivedAt:null,geometryRouteIds:[],stages:[],memberships:[],practicalNotes:{zh:[],en:[]},videos:[],storyLinks:[],researchLinks:[]});await saveStudio(payload.value,doc,'route',id,`新建路线：${name.value.trim()}`);message.value='新路线草稿已建立。';creating.value=false;name.value='';await load()}
</script>
<template><div class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">路线</p><h1>路线维护</h1><p>路线阶段、路线分组和地点角色在这里统一调整。</p></div><button class="primary-action" @click="creating=!creating">＋ 新建路线</button></div><p v-if="message" class="inline-message">{{message}}</p><section v-if="creating" class="visual-add-panel"><label>路线中文名称<input v-model="name" placeholder="例如：自然观察路线"></label><p>新路线先作为草稿建立，不会自动加入现有地点，也不会编写内容。</p><button :disabled="!name.trim()" @click="create">建立路线草稿</button></section><div class="studio-route-list"><RouterLink v-for="route in payload?.document.routes.filter(r=>!r.archivedAt)" :key="route.id" :to="`/studio/routes/${route.id}`"><span class="route-road-icon">路</span><div><small>{{route.published?'公开路线':'草稿路线'}} · {{route.memberships.filter(m=>m.visible).length}} 个地图点</small><h2>{{route.name.zh}}</h2><p>{{route.summary.zh||'尚未填写路线简介'}}</p></div><b>编辑 →</b></RouterLink></div></div></template>
